import os
import sys
import json
from functools import lru_cache
#
sys.path.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "ocr"))
from ocr.ocr import run_ocr_inference, extract_bbox_list

NID_JSON = os.path.join("..", "..", "json", "nid.json")
END_TOKEN = "<|im_end|>"
THINK_OPEN = "<think>\n"
THINK_CLOSE = "\n</think>\n\n"

#

# Code generated by Claude: follows what I have written in 
# internal/services/ocr.py. Uses the same function calls,
# just migrated it to make it align with the prompt defined
# which includes: bbox, json_schema.

_ocr_model = None

def _get_ocr_model():
    global _ocr_model
    if _ocr_model is None:
        from paddleocr import PaddleOCR
        _ocr_model = PaddleOCR(
            text_detection_model_name = "PP-OCRv6_medium_det",
            text_recognition_model_name = "PP-OCRv6_medium_rec",
            engine = "transformers",
            use_doc_orientation_classify = False,
            use_doc_unwarping = False,
            use_textline_orientation = False,
        )
    return _ocr_model

def get_schema_nid() -> str:
    """
    Since the only images that we have available are ID cards,
    we will only be using ID cards as the JSON schema for our
    extraction inside of this KD compression.
    """
    with open(NID_JSON, "r", encoding = "utf-8") as f:
        return json.dumps(json.load(f), ensure_ascii = False)

@lru_cache(maxsize = None)
def get_bbox_coord(img_path : str) -> str:
    """
    Runs the OCR on the image and returns the bbox coordinates of the
    detected text lines as a string. Cached per image, so each image
    is only run through the OCR once per process.
    """
    inf_res = run_ocr_inference(ocr_model = _get_ocr_model(), img_path = img_path)
    bbox_list = extract_bbox_list(inf_res = inf_res)
    return json.dumps([bbox.tolist() for bbox in bbox_list])

def get_prompt(img_path : str) -> str:
    return (
        "Extract the fields from this document as JSON, following exactly this schema:\n"
        f"{get_schema_nid()}\n\n"
        "The document is bilingual (Khmer and English). Fields with `_km` in the name "
        "must be copied in Khmer script exactly as printed, and fields with `_en` in "
        "the name must be in English (Latin script). `characteristic` is written in "
        "Khmer. Never copy the English text into a `_km` field or the Khmer text into "
        "an `_en` field. Leave a field as \"\" if it is not on the document.\n\n"
        "These are the bounding boxes (four corner points, in pixels) of the text lines "
        "detected in the image:\n"
        f"{get_bbox_coord(img_path)}\n\n"
        "Respond with only the JSON object, no explanation."
    )

def build_chat_prompt(processor, img_path : str) -> str:
    """
    The thinking models' chat template always opens a <think> block for
    the answer. Closing it empty (Qwen's no-thinking format) makes the
    model answer with the JSON directly. Shared by training and generation
    so both see the exact same prompt.
    """
    messages = [{"role": "user", "content": [{"type": "image"}, {"type": "text", "text": get_prompt(img_path)}]}]
    prompt = processor.apply_chat_template(messages, add_generation_prompt = True)
    if prompt.endswith(THINK_OPEN):
        prompt += THINK_CLOSE
    return prompt
